schema_ddl:
CREATE TYPE stato_registrazione AS ENUM ('bozza', 'approvato', 'annullato');

CREATE TABLE centri_costo (
    id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    codice TEXT NOT NULL UNIQUE,
    descrizione TEXT
);

CREATE TABLE conti_contabili (
    id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    codice_conto TEXT NOT NULL UNIQUE,
    nome_conto TEXT NOT NULL
);

CREATE TABLE registrazioni_contabili (
    id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    data_registrazione DATE NOT NULL DEFAULT CURRENT_DATE,
    fase_contabile stato_registrazione NOT NULL,
    descrizione_generale TEXT
);

CREATE TABLE movimenti_contabili (
    id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    registrazione_id INT NOT NULL REFERENCES registrazioni_contabili(id),
    conto_id INT NOT NULL REFERENCES conti_contabili(id),
    valore_economico_operazione NUMERIC(15, 2) NOT NULL CHECK (valore_economico_operazione <> 0),
    segno_movimento TEXT NOT NULL CHECK (segno_movimento IN ('dare', 'avere'))
);

CREATE TABLE report_aggregati (
    id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    data_report DATE NOT NULL,
    centro_costo_id INT REFERENCES centri_costo(id),
    totale_periodo NUMERIC(18, 2) DEFAULT 0,
    note TEXT
);
